        4738,4738
    }
    local EXPECT_AUDIO_SIZE = 171613

    pcall(function() math.randomseed(os.time() + os.clock() * 10000) end)
    local nonceCounter = 0
    local function nextNonce()
        nonceCounter = nonceCounter + 1
        local t = math.floor(os.clock() * 1000) + nonceCounter * 7919
        local s = ""
        for k = 0, 2 do
            s = s .. string.char((math.floor(t / (256 ^ k)) + nonceCounter * 31 + k * 17) % 256)
        end
        for _ = 1, 4 do
            s = s .. string.char(math.random(0, 255))
        end
        return s
    end

    -- JPEG comment segment right after SOI (decoder-ignored) -> unique content per run
    local function jpegWithNonce(raw, nb)
        local len = #nb + 2
        local seg = string.char(255, 234, math.floor(len / 256), len % 256) .. nb
        return raw:sub(1, 2) .. seg .. raw:sub(3)
    end

    -- trailing bytes after the last MP3 frame (universally ignored, like ID3v1)
    local function audioWithNonce(raw, nb)
        return raw .. nb
    end

    local function decodeBase64(value)
        local fast
        pcall(function()
            if crypt and crypt.base64decode then fast = crypt.base64decode(value)
            elseif crypt and crypt.base64 and crypt.base64.decode then fast = crypt.base64.decode(value)
            elseif syn and syn.crypt and syn.crypt.base64 and syn.crypt.base64.decode then fast = syn.crypt.base64.decode(value) end
        end)
        if fast then return fast end
        local alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
        local rev = {}
        for i = 1, #alphabet do rev[alphabet:sub(i, i)] = i - 1 end
        local clean = value:gsub("[^" .. alphabet .. "=]", "")
        local out = {}
        for i = 1, #clean, 4 do
            local c1 = rev[clean:sub(i, i)]
            local c2 = rev[clean:sub(i + 1, i + 1)]
            local c3 = rev[clean:sub(i + 2, i + 2)]
            local c4 = rev[clean:sub(i + 3, i + 3)]
            if not c1 or not c2 then break end
            out[#out + 1] = string.char(c1 * 4 + math.floor(c2 / 16))
            if c3 then out[#out + 1] = string.char((c2 % 16) * 16 + math.floor(c3 / 4)) end
            if c3 and c4 then out[#out + 1] = string.char((c3 % 4) * 64 + c4) end
        end
        return table.concat(out)
    end

    local FRAME_W, FRAME_H = 440, 288
    local COLS, ROWS   = 2, 3
    local PER_SHEET    = COLS * ROWS
    local PREFETCH     = 6 -- sheets kept warm ahead of the playhead (~0.7s of lead)
    local TOTAL_FRAMES = 638 -- 60 FPS display slots (~10.63s); 524 unique frames (exact duplicates stored once)
    local FPS          = 60

    local gui = Instance.new("ScreenGui")
    gui.Name           = "FRHubPureSpriteIntro"
    gui.ResetOnSpawn   = false
    gui.IgnoreGuiInset = true
    gui.DisplayOrder   = 2147483647
    gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
    pcall(function() if syn and syn.protect_gui then syn.protect_gui(gui) end end)
    pcall(function() gui.Parent = root end)
    if not gui.Parent then gui.Parent = playerGui end

    local bg = Instance.new("Frame")
    bg.Size             = UDim2.new(1, 0, 1, 0)
    bg.BackgroundColor3 = Color3.new(0, 0, 0)
