    local skipStroke = Instance.new("UIStroke", skip)
    skipStroke.Color     = Color3.fromRGB(100, 205, 255)
    skipStroke.Thickness = 1

    local finished = false
    local playbackStarted = false
    local fallbackShown = false
    local sound

    local function finish()
        if finished then return end
        finished = true
        pcall(function()
            if sound then
                TS:Create(sound, TweenInfo.new(0.35), {Volume = 0}):Play()
                task.delay(0.4, function() pcall(function() sound:Destroy() end) end)
            end
        end)
        pcall(function()
            TS:Create(fade, TweenInfo.new(0.3), {BackgroundTransparency = 0}):Play()
        end)
        task.delay(0.35, function()
            pcall(function() gui:Destroy() end)
            if onComplete then task.spawn(onComplete) end
        end)
    end
    skip.MouseButton1Click:Connect(finish)
    skip.Activated:Connect(finish)

    -- stay on top: re-assert parent/display-order in case other scripts try to push UI over it
    task.spawn(function()
        while not finished and gui.Parent do
            pcall(function()
                gui.DisplayOrder = 2147483647
                gui.Enabled = true
                if gui.Parent ~= root then gui.Parent = root end
            end)
            task.wait(1)
        end
    end)

    task.spawn(function()
        local d = 0
        while not finished and loading.Parent and loading.Visible do
            d = (d % 3) + 1
            loading.Text = "LOADING INTRO" .. string.rep(".", d)
            task.wait(0.3)
        end
    end)

    local function fallbackIntro()
        if finished or fallbackShown then return end
        fallbackShown = true
        pcall(function() holder.Visible = false end)
        loading.Visible = false
        barBg.Visible   = false

        local title = Instance.new("TextLabel")
        title.AnchorPoint            = Vector2.new(0.5, 0.5)
        title.Position               = UDim2.new(0.5, 0, 0.5, -10)
        title.Size                   = UDim2.new(1, 0, 0, 60)
        title.BackgroundTransparency = 1
        title.Text                   = "PURE HUB"
        title.TextColor3             = Color3.fromRGB(240, 250, 255)
        title.Font                   = Enum.Font.GothamBlack
        title.TextSize               = 30
        title.TextTransparency       = 1
        title.ZIndex                 = 10
        title.Parent                 = gui
        local ts2 = Instance.new("UIStroke", title)
        ts2.Color        = Color3.fromRGB(40, 130, 255)
        ts2.Thickness    = 2.5
        ts2.Transparency = 1

        local sub2 = Instance.new("TextLabel")
        sub2.AnchorPoint            = Vector2.new(0.5, 0.5)
        sub2.Position               = UDim2.new(0.5, 0, 0.5, 32)
        sub2.Size                   = UDim2.new(1, 0, 0, 20)
        sub2.BackgroundTransparency = 1
        sub2.Text                   = "S T E A L   A   B R A I N R O T"
        sub2.TextColor3             = Color3.fromRGB(120, 195, 255)
        sub2.Font                   = Enum.Font.GothamBold
        sub2.TextSize               = 13
        sub2.TextTransparency       = 1
        sub2.ZIndex                 = 10
        sub2.Parent                 = gui

        TS:Create(title, TweenInfo.new(0.7, Enum.EasingStyle.Back, Enum.EasingDirection.Out),
            {TextTransparency = 0, TextSize = 52}):Play()
        TS:Create(ts2,  TweenInfo.new(0.7), {Transparency = 0.2}):Play()
        TS:Create(sub2, TweenInfo.new(0.8), {TextTransparency = 0.05}):Play()
        task.delay(2.2, finish)
    end

    task.spawn(function()
        local ok, err = pcall(function()
            if not (getAsset and writefile) then
                error("executor lacks writefile/getcustomasset")
            end

            local assets = {}
            local labels = {}

            pcall(function()
                if delfile and isfile then
                    for i = 1, 120 do
                        for _, old in ipairs({"intro_mp4_11s_sheet", "intro_mp4_60_sheet", "intro_mp4_v3_sheet", "intro_mp4_v4_sheet", "intro_v5_sheet"}) do
                            local fn = old .. i .. ".jpg"
                            if isfile(fn) then pcall(delfile, fn) end
                        end
                    end
                    for _, old in ipairs({"intro_mp4_soundtrack.mp3", "intro_v6_soundtrack.mp3"}) do
                        if isfile(old) then pcall(delfile, old) end
                    end
                end
            end)

            local function writeSheet(i)
                if finished then return nil end
                local encoded = SHEET_DATA[i]
                local raw = encoded and decodeBase64(encoded)
                if not raw or #raw ~= EXPECT_SIZE[i] then return nil end
                local fn = "intro_v7_sheet" .. i .. ".jpg"
                pcall(writefile, fn, jpegWithNonce(raw, nextNonce()))
                task.wait()
                local okA, a = pcall(getAsset, fn)
                if okA and a then return a end
                return nil
            end

            for i = 1, #SHEET_DATA do
                assets[i] = writeSheet(i)
                if finished then return end
                pcall(function() bar.Size = UDim2.new(i / #SHEET_DATA, 0, 1, 0) end)
            end

            loading.Text = "STARTING..."

            -- sound: fresh content + up to 3 attempts, verified through IsLoaded
            pcall(function()
                local audioRaw = decodeBase64(AUDIO_DATA)
                if not audioRaw or #audioRaw ~= EXPECT_AUDIO_SIZE then return end
                for attempt = 1, 3 do
                    if finished then return end
                    local fn = "intro_v7_soundtrack.mp3"
                    pcall(writefile, fn, audioWithNonce(audioRaw, nextNonce()))
                    task.wait(0.25)
                    local okA, a = pcall(getAsset, fn)
                    if okA and a then
                        local s = Instance.new("Sound")
                        s.SoundId = a
                        s.Volume  = 0.65
                        s.Parent  = SndSvc
                        local t0 = os.clock()
                        while os.clock() - t0 < 2 and not finished do
                            local okI, loaded = pcall(function() return s.IsLoaded end)
                            if okI and loaded then break end
                            task.wait(0.1)
                        end
                        local okI, loaded = pcall(function() return s.IsLoaded end)
                        if okI and loaded then
                            sound = s
                            return
                        end
                        pcall(function() s:Destroy() end)
                    end
                    pcall(function() if delfile then delfile(fn) end end)
                end
            end)

            -- best-effort image verification: rebuild any sheet the engine reports as failed
            pcall(function()
                local FAILED = Enum.AssetFetchStatus.Failed
                local failedSet = {}
                local verifyDone = false
                task.spawn(function()
                    pcall(function()
                        CP:PreloadAsync(assets, function(contentId, status)
                            if status == FAILED then failedSet[contentId] = true end
                        end)
                    end)
                    verifyDone = true
                end)
                local t0 = os.clock()
                while not verifyDone and os.clock() - t0 < 2 and not finished do task.wait(0.1) end
                for i = 1, #assets do
                    if failedSet[assets[i]] and not finished then
                        assets[i] = writeSheet(i)
                    end
                end
            end)

            for i = 1, #assets do
                if not assets[i] then
                    error("sheet " .. i .. " failed to load")
                end
            end

            -- release the big embedded strings + run GC so the collector cannot
            -- hitch the first seconds of playback
            SHEET_DATA = nil
            AUDIO_DATA = nil
            pcall(collectgarbage, "collect")

            -- lazy sheet labels: only the warm window exists at any time (~20MB VRAM).
            -- Sheets are created ~0.7s before needed and destroyed behind the playhead.
            local function ensureLabel(i)
                local lab = labels[i]
                if lab then return lab end
                lab = Instance.new("ImageLabel")
                lab.Size                   = UDim2.new(1, 0, 1, 0)
                lab.BackgroundTransparency = 1
                lab.BorderSizePixel        = 0
                lab.ScaleType              = Enum.ScaleType.Stretch
                lab.ImageRectSize          = Vector2.new(FRAME_W, FRAME_H)
                lab.ImageRectOffset        = Vector2.new(0, 0)
                lab.ZIndex                 = 3
                lab.Image                  = assets[i]
                lab.Visible                = true
                lab.Parent                 = holder
                labels[i] = lab
                return lab
            end

            local function dropLabel(i)
                local lab = labels[i]
                if lab then
                    labels[i] = nil
                    lab:Destroy()
                end
            end

            local curWindow = 0
            local function activate(s)
                if s == curWindow then return end
                for k = 0, PREFETCH do
                    local t = s + k
                    if assets[t] then
                        local lab = ensureLabel(t)
                        lab.ZIndex  = 3 + PREFETCH - k
                        lab.Visible = true
                    end
                end
                local lo = math.min(curWindow, s)
                local hi = math.max(curWindow, s) + PREFETCH
                for t = lo, hi do
                    if (t < s or t > s + PREFETCH) and labels[t] then
                        dropLabel(t)
                    end
                end
                curWindow = s
            end

            activate(1)

            -- short warm-up: decode the opening window under the black overlay
            local t0 = os.clock()
            while os.clock() - t0 < 0.5 and not finished do
                RS.RenderStepped:Wait()
            end
            if finished then return end

            loading.Visible = false
            barBg.Visible   = false
            TS:Create(fade, TweenInfo.new(0.25), {BackgroundTransparency = 1}):Play()
            if sound then pcall(function() sound:Play() end) end
            playbackStarted = true
            task.delay(15, finish)

            local start = os.clock()
            local shown = -1
            local conn
            conn = RS.RenderStepped:Connect(function()
                if finished then
                    pcall(function() conn:Disconnect() end)
                    return
                end
                local idx = math.floor((os.clock() - start) * FPS)
                if idx >= TOTAL_FRAMES then
                    pcall(function() conn:Disconnect() end)
                    finish()
                    return
                end
                local uidx = FRAME_MAP[idx + 1]
                if uidx ~= shown then
                    shown = uidx
                    local sheet   = math.floor((uidx - 1) / PER_SHEET) + 1
                    local local_i = (uidx - 1) % PER_SHEET
                    if sheet ~= curWindow then
                        activate(sheet)
                    end
                    local lab = labels[sheet]
                    if lab then
                        lab.ImageRectOffset = Vector2.new(
                            (local_i % COLS) * FRAME_W,
                            math.floor(local_i / COLS) * FRAME_H
                        )
                    end
                end
            end)
        end)

        if not ok then
            pcall(function() warn("[FRHubIntro] " .. tostring(err)) end)
        end
        if not playbackStarted and not finished then
            fallbackIntro()
        end
    end)

    task.delay(45, function()
        if not playbackStarted and not finished then fallbackIntro() end
    end)
    task.delay(90, finish)
end

_G.FRHUB_VIDEO_INTRO_FINISHED = false
_runIntro(function()
    _G.FRHUB_VIDEO_INTRO_FINISHED = true
end)
